// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 _val) internal {
        bool firstReverted;
        try c.Initialized() { firstReverted = false; } catch { firstReverted = true; }
        bool secondReverted;
        try c.SetMinSum(_val) { secondReverted = false; } catch { secondReverted = true; }
        assertTrue(!firstReverted && secondReverted);
    }

    function testFuzz_run(uint256 _val) public {
        _run(_val);
    }

    receive() external payable {}
}
